arguments.cmd:
cd /tmp && rm -rf rotonly && mkdir rotonly && cd rotonly && cat > model.scad <<'EOF'
part = "assembly"; // ["disc", "finger", "assembly"]
cadverify_only = "";
module instance(name, part, unit = 1) {
    echo(cadverify_instance = [name, part, unit]);
    if (cadverify_only == "" || cadverify_only == name) children();
}
module disc() {
    difference() {
        cylinder(r = 11, h = 2.5, $fn = 72);
        translate([0, 0, -1]) cylinder(r = 3.4, h = 5, $fn = 36);
        for (a = [0, 90, 180, 270])
            rotate([0, 0, a]) translate([-1.3, -11.8, -0.1]) cube([2.6, 4, 2.7]);
    }
}
module finger() {
    cube([30, 25, 3]);
    translate([15, 6.1, 2.5]) rotate([-40.85, 0, 0])
        translate([-2.52, -0.84, 0]) cube([5.04, 1.68, 11.77]);
    translate([15 - 2.52, 14.1, 9.4]) cube([5.04, 4.5, 1.5]);
    translate([15, 18.6, 9.4]) cylinder(r = 0.65, h = 1.5, $fn = 24);
}
if (part == "disc") {
    echo(cadverify_spec = [
        ["bounds", [[-11, -12, 0], [11, 11, 2.5]]],
        ["bodies", 1], ["through_holes", 1],
        ["support_faces", [["bed", "-z", 100]]],
        ["overhangs_allowed", []],
        ["copies", 1], ["material", "PLA"],
        ["details", []]]);
    disc();
} else if (part == "finger") {
    echo(cadverify_spec = [
        ["bounds", [[0, 0, 0], [30, 25, 10.9]]],
        ["bodies", 1], ["through_holes", 0],
        ["support_faces", [["bed", "-z", 500]]],
        ["overhangs_allowed", [["u", [[12, 3.5, 2.0], [18, 21.2, 10.5]]]]],
        ["copies", 1], ["material", "PLA"],
        ["details", []]]);
    finger();
} else if (part == "assembly") {
    echo(cadverify_spec = [
        ["bounds", [[0, 0, 0], [30, 25, 12.5]]],
        ["allowed_interferences", []],
        ["motions", [["m", ["disc"], "rotate", [15, 30, 0], [0, 0, 1], [0, 360],
            ["flex", [["disc", "finger", 0.5, "test", [2, 10]]]],
            ["rests", [0, 90, 180, 270, 360]]]]],
        ["assembly_order", [[["disc", "finger"], [0, 0, 0]]]],
        ["material", "PLA"]]);
    instance("disc", "disc") translate([15, 30, 10]) disc();
    instance("finger", "finger") finger();
}
EOF
timeout 200 cadcheck assembly --out-dir /tmp/rotonly/aout model.scad 2>&1 | python -c "import json,sys; d=json.load(sys.stdin); print('ok:',d['ok']); print('G3:',str(d['problems']['G3'])[:800]); print('G4:',str(d['problems']['G4'])[:2500])"
